import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

const bilesenYolu = path.resolve(import.meta.dirname, '../src/SayacPaneli.svelte');
const ham = fs.readFileSync(bilesenYolu, 'utf8');
const yorumsuzHtml = ham.replace(/<!--[\s\S]*?-->/g, '');
if (/\bstyle\s*=/.test(yorumsuzHtml)) {
  throw new Error('CSP ihlali: sabit style özniteliği kullanılamaz');
}
const scriptEslesme = yorumsuzHtml.match(/<script[^>]*>([\s\S]*?)<\/script>/);
assert.ok(scriptEslesme, '<script> bloğu bulunamadı');
const govde = yorumsuzHtml.slice(scriptEslesme.index + scriptEslesme[0].length);

assert.match(govde, /data-testid="sayac-degeri"\s*>\s*\{sayac\}\s*<\/span>/);
assert.match(govde, /data-testid="secili-etiket"\s*>\s*\{seciliEtiket\s*\?\?\s*'Yok'\}\s*<\/span>/);
const artirDugme = govde.match(/<button[^>]*data-testid="artir-dugmesi"[^>]*onclick=\{([^}]+)\}[^>]*>/);
const sifirlaDugme = govde.match(/<button[^>]*data-testid="sifirla-dugmesi"[^>]*onclick=\{([^}]+)\}[^>]*>/);
assert.ok(artirDugme, 'artir-dugmesi onclick bağlaması bulunamadı');
assert.ok(sifirlaDugme, 'sifirla-dugmesi onclick bağlaması bulunamadı');

const geciciTs = path.resolve(import.meta.dirname, './_derlenen_bilesen.ts');
const tsKodu = [
  'function $state<T>(baslangic: T): T { return baslangic; }',
  scriptEslesme[1],
  'export function _bagla() {',
  '  return {',
  '    oku: () => ({',
  '      sayacDegeri: String(sayac),',
  "      seciliEtiket: String(seciliEtiket ?? 'Yok'),",
  '    }),',
  '    artirTikla: (' + artirDugme[1] + '),',
  '    sifirlaTikla: (' + sifirlaDugme[1] + '),',
  '  };',
  '}',
].join('\n');
fs.writeFileSync(geciciTs, tsKodu, 'utf8');
try {
  const mod = await import(pathToFileURL(geciciTs).href);
  const ornek = mod._bagla();
  assert.deepEqual(ornek.oku(), { sayacDegeri: '0', seciliEtiket: 'Yok' });
  ornek.artirTikla();
  assert.deepEqual(ornek.oku(), { sayacDegeri: '1', seciliEtiket: 'önemli' });
  ornek.artirTikla();
  assert.deepEqual(ornek.oku(), { sayacDegeri: '2', seciliEtiket: 'önemli' });
  ornek.sifirlaTikla();
  assert.deepEqual(ornek.oku(), { sayacDegeri: '0', seciliEtiket: 'Yok' });
  console.log('K03_UI_TESTI=TAMAM');
} finally {
  fs.rmSync(geciciTs, { force: true });
}
